import { ChakraProvider, Box, Heading, Button } from '@chakra-ui/react';
import { createRoot } from 'react-dom/client';

function App() {
  return (
    <ChakraProvider>
      <Box p={4}>
        <Heading color="blue.500">Hallo, Welt!</Heading>
        <Button colorScheme="blue">Klick mich</Button>
      </Box>
    </ChakraProvider>
  );
}

const root = createRoot(document.getElementById('root'));
root.render(<App />);
